D["社区话题4_角色2"] = "@价值投资者"
D["社区话题4_观点2"] = H(ORANGE, "布局看现金流") + "：" + H(RED, "银行/公用作底仓") + "，" + H(CYAN, "科技等业绩兑现") + "。"
D["社区话题4_角色3"] = "@谨慎派"
D["社区话题4_观点3"] = H(ORANGE, "别猜方向") + "：" + H(GREEN, "缩量不是底信号") + "，" + H(GREEN, "等放量再确认") + "。"
D["社区话题4_观点"] = "我的态度是" + H(RED, "“不急着减，也不急着加，先排结构”") + "。先看卖方共识：" + H(CYAN, "9月10日盘后汇总17家主流券商，12家定义为“缩量磨底/震荡结构市”、仅3家方向性看多、0家看空——卖方未见一家转空，但方向性多头同样稀缺") + "。盘面证据更诚实：" + H(GREEN, "成交缩至1.65万亿创下半年新低、连续四日跌破2万亿，上涨个股仅955只占比约17%，9月以来融资余额减少超120亿元") + "。" + H(ORANGE, "缩量普跌叠加银行独涨，通常对应存量博弈的中后段而不是新一轮启动——这种时候换仓，最常见的结局是卖在低点、买在另一轮的高点") + "。我的做法：" + H(RED, "红利底仓（银行/公用）与黄金定投不动") + "，" + H(CYAN, "高估值成长与纯题材仓位借反弹减一点") + "，" + H(CYAN, "总仓位控在七成以内留三成现金") + "，等产品、量能、外围三者共振（双节后概率更高）再动手。" + H(GREEN, "多看少动，比追涨杀跌更划算") + "。"
D["社区话题标签4"] = "缩量磨底"
